# models.py - the small CNN trained from scratch and the ResNet-18 used for transfer learning.
# Source note: adapted from code generated by Claude (Anthropic), Nov 2026.

import torch.nn as nn
from torchvision.models import resnet18, ResNet18_Weights


def block(c_in, c_out):
    # One CNN building block (used 3 times):
    #   Conv2d 3x3     - learns local patterns (edges -> shapes -> symbols); padding=1 keeps the size
    #   BatchNorm2d    - normalises activations per batch -> faster, more stable training
    #   ReLU           - non-linearity; without it the network would be one big linear function
    #   MaxPool2d(2)   - halves width and height -> less compute, more tolerant of small shifts
    return nn.Sequential(nn.Conv2d(c_in, c_out, 3, padding=1), nn.BatchNorm2d(c_out), nn.ReLU(), nn.MaxPool2d(2))


class SmallCNN(nn.Module):
    def __init__(self, n_classes=43, size=48):
        super().__init__()
        # 3 blocks: 3 -> 32 -> 64 -> 128 channels, image 48 -> 24 -> 12 -> 6 px.
        # Less spatial detail, more (and more abstract) feature maps.
        self.features = nn.Sequential(block(3, 32), block(32, 64), block(64, 128))
        # Classifier: flatten [128, 6, 6] to 4608 numbers -> 256 hidden units -> 43 class scores.
        # (size // 8) because 3 pooling layers divide the size by 8, so other input sizes also work.
        # Dropout(0.5) randomly turns off half the hidden units during training -> less overfitting.
        # Most of the ~1.28M parameters are in the first Linear layer (4608 x 256).
        self.classifier = nn.Sequential(nn.Flatten(), nn.Linear(128 * (size // 8) ** 2, 256),
                                        nn.ReLU(), nn.Dropout(0.5), nn.Linear(256, n_classes))

    def forward(self, x):
        # x: [batch, 3, 48, 48] -> raw class scores [batch, 43] (no softmax; CrossEntropyLoss does that)
        return self.classifier(self.features(x))


def build_model(name, size=48, freeze=False):
    # Returns the model chosen with --model in train.py ("cnn" or "resnet18")
    if name == "cnn":
        return SmallCNN(size=size)
    # ResNet-18 with ImageNet weights (allowed starting point under the course rules)
    m = resnet18(weights=ResNet18_Weights.IMAGENET1K_V1)
    if freeze:
        # Frozen feature extractor: no backbone weights are updated
        for q in m.parameters():
            q.requires_grad = False
    # Replace the 1000-class ImageNet output layer with a new 43-class layer.
    # It is created AFTER freezing, so it is trainable (512 * 43 + 43 = 22,059 parameters).
    m.fc = nn.Linear(512, 43)
    return m
